x.legend_css:
@import url('https://fonts.googleapis.com/css2?family=Open+Sans&display=swap');

#legend-2e8b3 h2 {
  font-size: 14px;
  font-family: 'Open Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  line-height: 20px;
  margin-bottom: 10px;
  margin-top: 0px;
}

#legend-2e8b3 {
  position: absolute;
  border-radius: 10px;
  margin: 10px;
  width: 200px;
  background-color: #ffffff80;
  padding: 10px 20px;
  z-index: 1002;
}

#legend-2e8b3.top-left {
  top: 10px;
  left: 10px;
}

#legend-2e8b3.bottom-left {
  bottom: 10px;
  left: 10px;
}

#legend-2e8b3.top-right {
  top: 10px;
  right: 10px;
}

#legend-2e8b3.bottom-right {
  bottom: 10px;
  right: 10px;
}

#legend-2e8b3 .legend-gradient {
  height: 20px;
  margin: 5px 10px 5px 10px;
  border-radius: 3px;
}

#legend-2e8b3[data-ramp-picker='true'] .legend-gradient {
  cursor: pointer;
  outline: 1px solid rgba(17, 24, 39, 0.16);
  outline-offset: 0;
}

#legend-2e8b3 .mapgl-ramp-picker {
  position: relative;
  height: 0;
  margin: 0 10px;
}

#legend-2e8b3 .mapgl-ramp-picker-swatch {
  display: inline-block;
  height: 14px;
  border-radius: 3px;
  border: 1px solid rgba(17, 24, 39, 0.16);
  flex: 1 1 auto;
  min-width: 64px;
}

#legend-2e8b3 .mapgl-ramp-picker-label {
  flex: 0 0 auto;
  white-space: nowrap;
}

#legend-2e8b3 .mapgl-ramp-picker-no-labels .mapgl-ramp-picker-swatch {
  min-width: 100%;
}

#legend-2e8b3 .mapgl-ramp-picker-no-labels .mapgl-ramp-picker-option {
  padding: 6px;
}

#legend-2e8b3 .mapgl-ramp-picker-menu {
  position: absolute;
  top: 4px;
  left: 0;
  right: 0;
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 6px;
  border: 1px solid rgba(17, 24, 39, 0.14);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
  z-index: 1004;
}

#legend-2e8b3.bottom-left .mapgl-ramp-picker-menu,
#legend-2e8b3.bottom-right .mapgl-ramp-picker-menu {
  top: auto;
  bottom: 4px;
}

#legend-2e8b3 .mapgl-ramp-picker.mapgl-ramp-picker-open .mapgl-ramp-picker-menu {
  display: flex;
}

#legend-2e8b3 .mapgl-ramp-picker-option {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  padding: 5px 6px;
  text-align: left;
}

#legend-2e8b3 .mapgl-ramp-picker-option:hover,
#legend-2e8b3 .mapgl-ramp-picker-option[data-selected='true'] {
  background: rgba(15, 23, 42, 0.08);
}

#legend-2e8b3 .legend-labels {
  position: relative;
  height: 20px;
  margin: 0 10px;
}

#legend-2e8b3 .legend-labels span {
  font-size: 12px;
  position: absolute;
  transform: translateX(-50%);  /* Center all labels by default */
  white-space: nowrap;
}
